5	/**
6	 * The single definition of an owner's locality: the canonical region derived from its
7	 * postcode range first (see {@link Postcode}), falling back to a fixed city-to-region table
8	 * when the postcode is absent or in no known range. Owners matching neither resolve to
9	 * {@code "UNKNOWN"}.
10	 *
11	 * <p>Lookup only; a pure function of the postcode and city, so the region is computed on read
12	 * rather than stored.
13	 */
14	public final class Locality {
15	
16	    /** The unknown-region marker returned for any city not in {@link #CITY_REGION}. */
17	    public static final String UNKNOWN = "UNKNOWN";
18	
19	    /** City -> canonical region. */
20	    private static final Map<String, String> CITY_REGION =
21	            Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
22	
23	    private Locality() {
24	    }
25	
26	    /** The canonical region for {@code city} via the city-to-region table alone, or
27	     *  {@code "UNKNOWN"} when it is not in the table. */
28	    public static String region(String city) {
29	        return CITY_REGION.getOrDefault(city, UNKNOWN);
30	    }
31	
32	    /** The canonical region for an owner: the postcode's region when its range identifies one,
33	     *  otherwise the city's region, or {@code "UNKNOWN"} when neither applies. */
34	    public static String region(String city, String postcode) {
35	        String byPostcode = Postcode.region(postcode);
36	        return byPostcode != null ? byPostcode : region(city);
37	    }
38	}
