44	
45	    /** The owner's derived identity key: normalized telephone, email and household id joined. */
46	    default String identityKey(Owner owner) {
47	        return IdentityKey.of(owner);
48	    }
49	
50	    /** Whether the owner was flagged as a possible duplicate at registration, i.e. it carries
51	     *  the id of an existing owner it possibly duplicates. */
52	    default boolean possibleDuplicate(Owner owner) {
53	        return owner.getPossibleDuplicateOf() != null;
54	    }
