66	    private String initial(String name) {
67	        return name == null || name.isEmpty() ? "" : Character.toUpperCase(name.charAt(0)) + ".";
68	    }
69	
70	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
71	     *  last two digits of the registration date's year (e.g. 'SPR-SMI-0007-M26'). Absent until both the
